import type { T, Lang } from './lang';
import { guide, isGuide } from './guides';

// The words of sailboat racing, for /learn/glossary: each a short, plain definition (what search engines quote for
// "what is a layline", and AI assistants too), with the guide that goes further where there is one. In six groups,
// each in the order a sailor meets them.
export type GroupId = 'points-of-sail' | 'right-of-way' | 'wind' | 'start' | 'marks' | 'boat';
// en: the English name, for a reader in another language ("Поворот оверштаг (tack)"): without its own aside ("Tack
// (to tack)" is "tack"), lower case but for an abbreviation, and left out where the name already has it ("Layline",
// "VMG (скорость к цели)")
export type Term = { id: string; group: GroupId; term: string; def: string; see?: string; en?: string };

export function glossaryGroups(t: T): { id: GroupId; title: string; terms: Term[] }[] {
  const all = glossary(t);
  const groups: [GroupId, string][] = [
    ['points-of-sail', t('Points of sail and turns', 'Курсы и повороты', 'Rumbos y giros', 'Kurse zum Wind und Drehungen', 'Seyir açıları ve dönüşler', 'Allures et manœuvres', 'Andature e manovre', 'Andaduras e manobras')],
    ['right-of-way', t('Who keeps clear', 'Кто уступает', 'Quién se mantiene separado', 'Wer sich freihält', 'Kim uzak durur', 'Qui se maintient à l’écart', 'Chi si tiene discosto', 'Quem se mantém afastado')],
    ['wind', t('The wind', 'Ветер', 'El viento', 'Der Wind', 'Rüzgâr', 'Le vent', 'Il vento', 'O vento')],
    ['start', t('The start', 'Старт', 'La salida', 'Der Start', 'Start', 'Le départ', 'La partenza', 'A largada')],
    ['marks', t('The marks', 'Знаки', 'Las balizas', 'Die Bahnmarken', 'Şamandıralar', 'Les bouées', 'Le boe', 'As boias')],
    ['boat', t('The boat', 'Лодка', 'El barco', 'Das Boot', 'Tekne', 'Le bateau', 'La barca', 'O barco')],
  ];
  return groups.map(([id, title]) => ({ id, title, terms: all.filter((x) => x.group === id) }));
}

// what a term's see-link says, from where it goes: a section of the rules guide by its rule ("Rule 10"), any other
// guide by its name ("Guide: rounding the marks"), How to play by its own
export function seeLabel(href: string, t: T, lang: Lang): string {
  const [path, hash] = href.split('#');
  const slug = path.replace(/^\/learn\//, '');
  if (path.startsWith('/learn/') && isGuide(slug)) {
    const g = guide(slug, t, lang);
    const rule = hash && g.sections.find((s) => s.id === hash)?.h.match(/\((rules? [^)]*|правил[ао] [^)]*)\)/)?.[1];
    if (rule) return rule[0].toUpperCase() + rule.slice(1);
    const name = g.short[0].toLowerCase() + g.short.slice(1);
    return t(`Guide: ${name}`, `Пособие: ${name}`, `Guía: ${name}`, `Leitfaden: ${name}`, `Rehber: ${name}`, `Guide : ${name}`, `Guida: ${name}`, `Guia: ${name}`);
  }
  if (path === '/help') return t('How to play', 'Как играть', 'Cómo jugar', 'So spielst du', 'Nasıl oynanır', 'Comment jouer', 'Come si gioca', 'Como jogar');
  return t('More', 'Подробнее', 'Más', 'Mehr', 'Daha fazla', 'Plus', 'Altro', 'Mais');
}

// The sailing dictionary (/dictionary, a page for each word at /dictionary/<id>): the same words, each with its own
// address, and the ones that can be seen sailed on the water in 3D (public/word-view, the race's own scenes:
// public/game/word-scenes.js sceneIds for the JPK 1050, which npm test keeps this in step with). The rest are ideas
// (apparent wind, VMG), a person (the umpire) or too small to make out at that distance (telltales).
export const SCENES_3D: readonly string[] = [
  'beat', 'close-hauled', 'reach', 'run', 'tack', 'gybe', 'luff', 'bear-away', 'in-irons', 'starboard', 'port', 'windward', 'overlap',
  'clear-astern', 'proper-course', 'penalty', 'header', 'lift', 'layline', 'dirty-air', 'gust', 'start-line', 'favoured-end', 'ocs',
  'general-recall', 'windward-mark', 'zone', 'mark-room', 'gate', 'gennaker', 'sheet', 'reef', 'no-go', 'pinching', 'footing',
  'by-the-lee', 'crash-gybe', 'heel', 'keep-clear', 'veer-back', 'oscillating', 'persistent', 'current', 'committee-boat', 'pin',
  'starting-signal', 'line-bias', 'leg', 'offset-mark', 'wing-mark', 'wide-in', 'finish-line', 'mainsail', 'jib', 'boom', 'code-zero', 'backing',
];
export const dictPath = (id?: string) => (id ? `/dictionary/${id}` : '/dictionary');
export const dictName = (t: T) => t('Sailing dictionary', 'Словарь яхтсмена', 'Diccionario de vela', 'Segelwörterbuch', 'Yelken sözlüğü', 'Dictionnaire de la voile', 'Dizionario della vela', 'Dicionário de vela');

const EN: T = (en) => en;
const fold = (s: string) => s.toLowerCase().normalize('NFD').replace(/\p{M}/gu, '');
export function englishName(en: string): string {
  const head = en.replace(/\s*\([^)]*\)\s*$/, '');
  return /^[A-Z]{2,}\b/.test(head) ? head : head[0].toLowerCase() + head.slice(1);
}
export function glossary(t: T): Term[] {
  const own = words(t), en = words(EN);
  return own.map((x, i) => {
    const e = englishName(en[i].term);
    return fold(x.term).includes(fold(e)) ? x : { ...x, en: e };
  });
}

function words(t: T): Term[] {
  const terms: Term[] = [
    { id: 'beat', group: 'points-of-sail', term: t('Beat', 'Лавировка', 'Ceñida', 'Kreuz', 'Orsa', 'Bord de près', 'Bolina', 'Orça'), see: '/learn/shifts', def: t(
      'Sailing towards a mark that lies upwind. No boat can sail straight into the wind, so she zigzags towards it, close-hauled on one tack and then the other.',
      'Движение к знаку, который лежит против ветра. Прямо против ветра лодка идти не может, поэтому идёт зигзагом, в бейдевинд то одним, то другим галсом.', 'Navegar hacia una baliza que queda a barlovento. Ningún barco puede navegar directo contra el viento, así que va en zigzag hacia ella, de ceñida por una amura y luego por la otra.', 'Auf eine Bahnmarke zusegeln, die in Luv liegt. Kein Boot kann direkt gegen den Wind segeln, also zickzackt es darauf zu, hoch am Wind erst auf dem einen Bug, dann auf dem anderen.', 'Rüzgârın geldiği yönde bulunan bir şamandıraya doğru yelken açmak. Hiçbir tekne doğrudan rüzgâra yelken açamaz; bu yüzden zikzak çizer, önce bir kontrada sonra öbüründe orsa giderek.', 'Faire route vers une bouée située au vent. Aucun bateau ne peut remonter droit dans le vent, alors il zigzague vers elle, au près sur un bord puis sur l’autre.', 'Navigare verso una boa che si trova sopravvento. Nessuna barca può andare dritta controvento, così ci arriva a zigzag, di bolina stretta prima con una mura e poi con l’altra.', 'Velejar rumo a uma boia que fica a barlavento. Nenhum barco consegue velejar direto contra o vento, então ele ziguezagueia até ela, na orça em uma amura e depois na outra.') },
    { id: 'close-hauled', group: 'points-of-sail', term: t('Close-hauled', 'Бейдевинд', 'De ceñida', 'Hoch am Wind', 'Orsa', 'Au près', 'Di bolina stretta', 'Na orça'), def: t(
      'As close to the wind as the boat sails well, about 40° off it, with the sails pulled in hard.',
      'Курс так круто к ветру, как лодка ещё хорошо идёт, — около 40° к ветру, паруса выбраны туго.', 'Lo más cerca del viento que el barco navega bien, a unos 40° de él, con las velas cazadas a fondo.', 'So nah am Wind, wie das Boot gut segelt, etwa 40° vom Wind entfernt, mit hart dicht geholten Segeln.', 'Teknenin iyi yelken açtığı kadar rüzgâra yakın, rüzgârdan yaklaşık 40° açıyla, yelkenler sonuna kadar çekilmiş.', 'Aussi près du vent que le bateau avance bien, à environ 40° de lui, les voiles bordées à fond.', 'Il più vicino al vento che la barca riesce a navigare bene, a circa 40° da esso, con le vele cazzate a fondo.', 'O mais perto do vento que o barco veleja bem, a cerca de 40° dele, com as velas bem caçadas.') },
    { id: 'no-go', group: 'points-of-sail', term: t('No-go zone', 'Мёртвый угол', 'Ángulo muerto', 'Toter Winkel', 'Ölü açı', 'Zone interdite', 'Angolo morto', 'Zona morta'), see: '/learn/sail#nogo', def: t(
      'The angle either side of the wind, some 40° each way for a keelboat, into which no boat can sail. Steer into it and the sails flap and she slows to a stop.',
      'Сектор по обе стороны от направления ветра, около 40° в каждую сторону для килевой лодки, в котором идти невозможно. Зайдёшь в него — паруса заполощут, и лодка остановится.', 'El ángulo a cada lado del viento, unos 40° hacia cada lado en un barco de quilla, en el que ningún barco puede navegar. Si entras en él, las velas flamean y el barco se frena hasta pararse.', 'Der Winkel beiderseits des Windes, bei einem Kielboot etwa 40° nach jeder Seite, in den kein Boot segeln kann. Steuerst du hinein, killen die Segel und das Boot wird langsamer, bis es steht.', 'Rüzgârın her iki yanındaki, salmalı bir teknede her yöne yaklaşık 40°’lik açı; hiçbir tekne bu açıda yelken açamaz. İçine girersen yelkenler çırpar ve tekne yavaşlayıp durur.', 'L’angle de part et d’autre du vent, environ 40° de chaque côté pour un quillard, dans lequel aucun bateau ne peut naviguer. Si tu y entres, les voiles faseyent et le bateau ralentit jusqu’à s’arrêter.', 'L’angolo ai due lati del vento, circa 40° per parte su una barca a chiglia, in cui nessuna barca può navigare. Se ci entri, le vele sventano e la barca rallenta fino a fermarsi.', 'O ângulo de cada lado do vento, cerca de 40° para cada lado num veleiro de quilha, em que nenhum barco consegue velejar. Se entrar nele, as velas panejam e o barco perde velocidade até parar.') },
    { id: 'pinching', group: 'points-of-sail', term: t('Pinching', 'Идти слишком круто', 'Ir demasiado orzado', 'Kneifen', 'Fazla orsa', 'Pincer', 'Stringere troppo', 'Orçar demais'), see: '/learn/trim#foot', def: t(
      'Sailing closer to the wind than close-hauled. She points higher but slows, so she makes less way towards the mark, not more.',
      'Идти круче бейдевинда. Лодка смотрит выше, но теряет ход и в итоге приближается к знаку медленнее, а не быстрее.', 'Navegar más cerca del viento que de ceñida. El barco apunta más alto pero pierde velocidad, así que avanza menos hacia la baliza, no más.', 'Höher am Wind segeln als hoch am Wind. Das Boot zeigt höher, wird aber langsamer und kommt so der Marke weniger nah, nicht mehr.', 'Orsadan daha dar açıyla, rüzgâra fazla yakın seyretmek. Tekne daha yükseğe bakar ama yavaşlar; böylece şamandıraya daha az yaklaşır, daha çok değil.', 'Naviguer plus près du vent que le près serré. Le bateau pointe plus haut mais ralentit, et avance donc moins vers la bouée, pas plus.', 'Navigare più vicino al vento della bolina stretta. La barca punta più in alto ma rallenta, e così guadagna meno verso la boa, non di più.', 'Velejar mais perto do vento do que na orça. O barco aponta mais alto, mas perde velocidade, e assim avança menos rumo à boia, não mais.') },
    { id: 'footing', group: 'points-of-sail', term: t('Footing', 'Идти полнее для скорости', 'Arribar para ganar velocidad', 'Footen', 'Hız için açmak', 'Abattre pour accélérer', 'Poggiare per la velocità', 'Arribar para ganhar velocidade'), see: '/learn/trim#foot', def: t(
      'Sailing a few degrees lower than close-hauled, sheets a touch eased, to build speed: after a tack, in waves, or to break through to leeward of a boat.',
      'Идти на несколько градусов полнее бейдевинда, чуть потравив шкоты, чтобы набрать ход: после поворота, на волне или чтобы прорваться под ветер чужой лодки.', 'Navegar unos grados más abierto que de ceñida, con las escotas un poco sueltas, para ganar velocidad: tras una virada, con olas o para pasar a sotavento de otro barco.', 'Ein paar Grad tiefer als hoch am Wind segeln, die Schoten etwas gefiert, um Fahrt aufzubauen: nach einer Wende, in Wellen oder um in Lee an einem Boot vorbeizukommen.', 'Hız kazanmak için orsadan birkaç derece açık, iskotalar biraz laçka seyretmek: tramoladan sonra, dalgada ya da başka bir teknenin rüzgâraltından geçmek için.', 'Naviguer quelques degrés plus abattu que le près serré, les écoutes un peu choquées, pour prendre de la vitesse : après un virement, dans les vagues ou pour passer sous le vent d’un bateau.', 'Navigare qualche grado più poggiati della bolina stretta, con le scotte un filo lascate, per prendere velocità: dopo una virata, nell’onda o per passare sottovento a una barca.', 'Velejar alguns graus abaixo da orça, com as escotas um pouco soltas, para ganhar velocidade: depois de uma cambada, nas ondas ou para passar a sotavento de outro barco.') },
    { id: 'reach', group: 'points-of-sail', term: t('Reach', 'Галфвинд и бакштаг', 'Través', 'Raumschots', 'Apaz', 'Largue', 'Lasco', 'Través'), def: t(
      'Sailing with the wind across the boat: a tight reach a little upwind of square, a broad reach a little downwind.',
      'Курс, при котором ветер дует поперёк лодки: галфвинд — примерно в борт, бакштаг — сзади-сбоку.', 'Navegar con el viento cruzado al barco: un través cerrado, algo a barlovento de la perpendicular, y un largo, algo a sotavento.', 'Mit dem Wind quer zum Boot segeln: ein angeluvter Halbwindkurs etwas höher als rechtwinklig, ein Raumschotskurs etwas tiefer.', 'Rüzgârın tekneyi enine kestiği seyir: dar apaz tam yandan biraz rüzgâra doğru, geniş apaz biraz rüzgâraltına doğru.', 'Naviguer avec le vent par le travers du bateau : petit largue un peu plus au vent que le travers, grand largue un peu plus sous le vent.', 'Navigare con il vento di traverso alla barca: un lasco stretto poco sopra il traverso, un gran lasco poco sotto.', 'Velejar com o vento entrando pelo lado do barco: um través fechado, um pouco acima do través, e um largo, um pouco abaixo.') },
    { id: 'run', group: 'points-of-sail', term: t('Run', 'Фордевинд (курс)', 'Empopada', 'Vorwindkurs', 'Pupa', 'Vent arrière', 'Poppa', 'Popa'), see: '/learn/downwind', def: t(
      'Sailing with the wind from behind, towards a mark that lies downwind.',
      'Курс, при котором ветер дует сзади, к знаку, который лежит по ветру.', 'Navegar con el viento por detrás, hacia una baliza que queda a sotavento.', 'Mit dem Wind von hinten segeln, auf eine Bahnmarke zu, die in Lee liegt.', 'Rüzgâr arkadan gelirken, rüzgâraltındaki bir şamandıraya doğru yelken açmak.', 'Naviguer avec le vent dans le dos, vers une bouée située sous le vent.', 'Navigare con il vento da dietro, verso una boa che si trova sottovento.', 'Velejar com o vento por trás, rumo a uma boia que fica a sotavento.') },
    { id: 'by-the-lee', group: 'points-of-sail', term: t('By the lee', 'Бай-ли (ветер со стороны гика)', 'Navegar por la lee', 'Vor dem Wind mit falschem Baum', 'Bomun tarafından rüzgâr', 'Fausse panne', 'Strapoggio', 'Popa com o vento do lado da retranca'), see: '/learn/downwind#lee', def: t(
      'Running with the wind coming over the side the boom is on. A few degrees is fast in waves; much more and the boom slams across in a crash gybe.',
      'Попутный курс, при котором ветер приходит с того борта, где стоит гик. Несколько градусов на волне ускоряют, а больше — и гик перелетит в неуправляемом повороте.', 'Navegar en popa con el viento entrando por el lado donde está la botavara. Unos grados son rápidos con olas; muchos más, y la botavara cruza de golpe en una trasluchada involuntaria.', 'Vor dem Wind segeln, während der Wind von der Seite kommt, auf der der Baum steht. Ein paar Grad sind in Wellen schnell; viel mehr, und der Baum schlägt in einer Patenthalse über.', 'Rüzgârın bomun bulunduğu taraftan geldiği pupa seyri. Birkaç derece dalgada hızlıdır; çok fazlası olursa bom kontrolsüz bir kavançayla karşı tarafa çarpar.', 'Courir au vent arrière avec le vent qui arrive du côté de la bôme. Quelques degrés vont vite dans les vagues ; beaucoup plus, et la bôme passe brutalement dans un empannage involontaire.', 'Andare in poppa con il vento che entra dal lato del boma. Qualche grado è veloce sull’onda; molto di più, e il boma passa di colpo in una strambata involontaria.', 'Velejar de popa com o vento entrando pelo lado em que está a retranca. Alguns graus são rápidos nas ondas; muito mais, e a retranca cruza de golpe num jibe involuntário.') },
    { id: 'tack', group: 'points-of-sail', term: t('Tack (to tack)', 'Поворот оверштаг', 'Virar (virada)', 'Wende (wenden)', 'Tramola (tramola atmak)', 'Virement de bord (virer)', 'Virata (virare)', 'Cambada (cambar)'), def: t(
      'Turning the bow through the wind, from one tack to the other. Until she is close-hauled on the new tack a tacking boat keeps clear of others (rule 13).',
      'Поворот, при котором лодка проходит линию ветра носом и переходит с галса на галс. Пока она не легла в бейдевинд на новом галсе, она уступает всем (правило 13).', 'Girar la proa a través del viento, de una amura a la otra. Hasta que está de ceñida en la nueva amura, un barco que vira se mantiene separado de los demás (regla 13).', 'Den Bug durch den Wind drehen, von einem Bug auf den anderen. Bis es auf dem neuen Bug hoch am Wind liegt, hält sich ein wendendes Boot von anderen frei (Regel 13).', 'Pruvayı rüzgârın içinden geçirerek bir kontradan ötekine dönmek. Tramola atan tekne, yeni kontrada orsaya gelene kadar diğerlerinden uzak durur (kural 13).', 'Faire passer l’étrave dans le lit du vent, d’un bord sur l’autre. Tant qu’il n’est pas au près sur le nouveau bord, un bateau qui vire se maintient à l’écart des autres (règle 13).', 'Passare con la prua attraverso il vento, da una mura all’altra. Finché non è di bolina stretta sulla nuova mura, una barca che vira si tiene discosta dalle altre (regola 13).', 'Passar a proa pelo vento, de uma amura para a outra. Até estar na orça na nova amura, um barco cambando se mantém afastado dos outros (regra 13).') },
    { id: 'gybe', group: 'points-of-sail', term: t('Gybe', 'Поворот фордевинд', 'Trasluchar', 'Halse', 'Kavança', 'Empannage', 'Strambata', 'Jibe'), see: '/learn/downwind', def: t(
      'Turning the stern through the wind, so the boom swings across to the other side.',
      'Поворот, при котором через линию ветра проходит корма и гик перебрасывается на другой борт.', 'Girar la popa a través del viento, de modo que la botavara pasa al otro lado.', 'Das Heck durch den Wind drehen, sodass der Baum auf die andere Seite schwingt.', 'Kıçı rüzgârın içinden geçirerek dönmek; böylece bom öbür yana savrulur.', 'Faire passer l’arrière dans le lit du vent, si bien que la bôme bascule de l’autre côté.', 'Passare con la poppa attraverso il vento, così che il boma passi dall’altro lato.', 'Passar a popa pelo vento, de modo que a retranca cruze para o outro lado.') },
    { id: 'crash-gybe', group: 'points-of-sail', term: t('Crash gybe', 'Неуправляемый поворот фордевинд', 'Trasluchada involuntaria', 'Patenthalse', 'Kontrolsüz kavança', 'Empannage involontaire', 'Strambata involontaria', 'Jibe involuntário'), see: '/learn/tack#crash', def: t(
      'A gybe nobody meant: sailing too far by the lee, the wind gets behind the mainsail and throws the boom across. In a breeze she rolls hard and rounds up.',
      'Поворот, которого никто не собирался делать: лодка ушла слишком далеко «бай-ли», ветер зашёл за грот и перебросил гик. В свежий ветер её резко кренит и разворачивает к ветру.', 'Una trasluchada que nadie buscaba: con el viento demasiado por el lado de la botavara, se mete detrás de la mayor y la lanza al otro lado. Con viento fuerte el barco escora de golpe y orza.', 'Eine Halse, die niemand wollte: zu weit vor dem Wind mit dem Baum auf der falschen Seite fällt der Wind hinter das Großsegel und wirft den Baum über. Bei frischem Wind krängt das Boot hart und schießt in den Wind.', 'Kimsenin istemediği bir kavança: rüzgâr bomun tarafından fazla gelince grandinin arkasına geçer ve bomu karşıya fırlatır. Sert havada tekne birden yatar ve rüzgâra döner.', 'Un empannage que personne n’a voulu : trop en fausse panne, le vent passe derrière la grand-voile et envoie la bôme de l’autre côté. Dans la brise, le bateau gîte fort et part au lof.', 'Una strambata che nessuno voleva: troppo in strapoggio, il vento passa dietro la randa e scaraventa il boma dall’altra parte. Con vento fresco la barca sbanda forte e orza.', 'Um jibe que ninguém quis: com o vento demais do lado da retranca, ele passa por trás da vela grande e joga a retranca para o outro lado. Com vento forte o barco aderna de repente e orça.') },
    { id: 'starboard', group: 'right-of-way', term: t('Starboard tack', 'Правый галс', 'Amura de estribor', 'Steuerbordbug', 'Sancak kontra', 'Tribord amures', 'Mure a dritta', 'Amurado a boreste'), see: '/learn/rules#r10', def: t(
      'Sailing with the wind coming over the boat’s starboard (right) side and the boom out to port. Port tack keeps clear of starboard (rule 10).',
      'Ветер дует в правый борт, гик вынесен влево. Лодка левого галса уступает лодке правого (правило 10).', 'Navegar con el viento entrando por el costado de estribor (derecha) del barco y la botavara fuera por babor. Babor se mantiene separado de estribor (regla 10).', 'Segeln mit dem Wind über die Steuerbordseite (rechts) des Bootes und dem Baum nach Backbord. Backbordbug hält sich von Steuerbordbug frei (Regel 10).', 'Rüzgârın teknenin sancak (sağ) tarafından gelip bomun iskeleye açık olduğu seyir. İskele kontra, sancak kontradan uzak durur (kural 10).', 'Naviguer avec le vent qui arrive par le côté tribord (droit) du bateau et la bôme à bâbord. Bâbord amures se maintient à l’écart de tribord amures (règle 10).', 'Navigare con il vento che arriva sul lato di dritta (destro) della barca e il boma a sinistra. Mure a sinistra si tiene discosta da mure a dritta (regola 10).', 'Velejar com o vento entrando pelo boreste (direita) do barco e a retranca para bombordo. Amurado a bombordo se mantém afastado de amurado a boreste (regra 10).') },
    { id: 'port', group: 'right-of-way', term: t('Port tack', 'Левый галс', 'Amura de babor', 'Backbordbug', 'İskele kontra', 'Bâbord amures', 'Mure a sinistra', 'Amurado a bombordo'), see: '/learn/rules#r10', def: t(
      'Sailing with the wind coming over the boat’s port (left) side and the boom out to starboard.',
      'Ветер дует в левый борт, гик вынесен вправо.', 'Navegar con el viento entrando por el costado de babor (izquierda) del barco y la botavara fuera por estribor.', 'Segeln mit dem Wind über die Backbordseite (links) des Bootes und dem Baum nach Steuerbord.', 'Rüzgârın teknenin iskele (sol) tarafından gelip bomun sancağa açık olduğu seyir.', 'Naviguer avec le vent qui arrive par le côté bâbord (gauche) du bateau et la bôme à tribord.', 'Navigare con il vento che arriva sul lato di sinistra della barca e il boma a dritta.', 'Velejar com o vento entrando pelo bombordo (esquerda) do barco e a retranca para boreste.') },
    { id: 'keep-clear', group: 'right-of-way', term: t('Keep clear', 'Уступать дорогу', 'Mantenerse separado', 'Sich freihalten', 'Uzak durmak', 'Se maintenir à l’écart', 'Tenersi discosto', 'Manter-se afastado'), see: '/learn/rules#r10', def: t(
      'What the boat without right of way must do: sail so that the other boat can hold her course without having to change it. Port keeps clear of starboard, windward of leeward, clear astern of clear ahead.',
      'Что обязана делать лодка, не имеющая права дороги: идти так, чтобы другая лодка могла держать свой курс, не меняя его. Левый галс уступает правому, наветренная — подветренной, чисто позади — чисто впереди.', 'Lo que debe hacer el barco sin derecho de paso: navegar de modo que el otro pueda mantener su rumbo sin tener que cambiarlo. Babor se mantiene separado de estribor, barlovento de sotavento, libre por la popa de libre por la proa.', 'Was das Boot ohne Wegerecht tun muss: so segeln, dass das andere seinen Kurs halten kann, ohne ihn ändern zu müssen. Backbordbug hält sich frei von Steuerbordbug, Luv von Lee, klar achteraus von klar voraus.', 'Geçiş hakkı olmayan teknenin yapması gereken: diğer tekne rotasını değiştirmek zorunda kalmadan sürdürebilsin diye seyretmek. İskele kontra sancak kontradan, rüzgârüstü rüzgâraltından, açık arkadaki açık öndekinden uzak durur.', 'Ce que doit faire le bateau qui n’a pas la priorité : naviguer de façon que l’autre puisse garder sa route sans avoir à la changer. Bâbord s’écarte de tribord, au vent de sous le vent, route libre derrière de route libre devant.', 'Ciò che deve fare la barca senza diritto di rotta: navigare in modo che l’altra possa mantenere la sua rotta senza doverla cambiare. Mure a sinistra si tiene discosta da mure a dritta, sopravvento da sottovento, libera dietro da libera avanti.', 'O que o barco sem direito de passagem deve fazer: velejar de modo que o outro possa manter seu rumo sem precisar mudá-lo. Bombordo se mantém afastado de boreste, barlavento de sotavento, livre à ré de livre à vante.') },
    { id: 'windward', group: 'right-of-way', term: t('Windward and leeward', 'Наветренный и подветренный', 'Barlovento y sotavento', 'Luv und Lee', 'Rüzgârüstü ve rüzgâraltı', 'Au vent et sous le vent', 'Sopravvento e sottovento', 'Barlavento e sotavento'), see: '/learn/rules#r11', def: t(
      'Windward is the side or the boat nearer the wind; leeward is the side or the boat away from it. Overlapped on the same tack, windward keeps clear (rule 11).',
      'Наветренный — борт или лодка ближе к ветру, подветренный — дальше от него. На одном галсе при связанности наветренная уступает (правило 11).', 'Barlovento es el costado o el barco más cercano al viento; sotavento es el costado o el barco más alejado de él. Con compromiso en la misma amura, el de barlovento se mantiene separado (regla 11).', 'Luv ist die Seite oder das Boot, das näher am Wind liegt; Lee ist die Seite oder das Boot, das von ihm abgewandt liegt. Überlappen sich Boote auf demselben Bug, hält sich das Luvboot frei (Regel 11).', 'Rüzgârüstü, rüzgâra daha yakın olan taraf ya da teknedir; rüzgâraltı ondan uzak olandır. Aynı kontrada bindirmedeyken rüzgârüstü uzak durur (kural 11).', 'Au vent, c’est le côté ou le bateau le plus près du vent ; sous le vent, le côté ou le bateau qui en est le plus loin. Engagés sur le même bord, le bateau au vent se maintient à l’écart (règle 11).', 'Sopravvento è il lato o la barca più vicini al vento; sottovento il lato o la barca più lontani. Ingaggiate con le stesse mure, la barca sopravvento si tiene discosta (regola 11).', 'Barlavento é o lado ou o barco mais perto do vento; sotavento é o lado ou o barco mais longe dele. Sobrepostos na mesma amura, o barco a barlavento se mantém afastado (regra 11).') },
    { id: 'overlap', group: 'right-of-way', term: t('Overlap', 'Связанность (перекрытие)', 'Compromiso', 'Überlappung', 'Bindirme', 'Engagement', 'Ingaggio', 'Sobreposição'), see: '/learn/rules#r11', def: t(
      'Two boats on the same tack are overlapped when neither is clear astern of the other. It decides who keeps clear and who gets room at a mark.',
      'Две лодки на одном галсе связаны, когда ни одна не находится чисто позади другой. Связанность решает, кто уступает и кому положено место у знака.', 'Dos barcos en la misma amura tienen compromiso cuando ninguno está libre por la popa del otro. Decide quién se mantiene separado y quién tiene espacio en una baliza.', 'Zwei Boote auf demselben Bug überlappen sich, wenn keines klar achteraus vom anderen ist. Sie entscheidet, wer sich freihält und wer an einer Bahnmarke Raum bekommt.', 'Aynı kontradaki iki tekne, hiçbiri öbürünün açık arkasında değilse bindirmededir. Kimin uzak duracağını ve şamandırada kimin alan alacağını belirler.', 'Deux bateaux sur le même bord sont engagés quand aucun n’est en route libre derrière l’autre. C’est ce qui décide qui se maintient à l’écart et qui a droit à la place à la marque.', 'Due barche con le stesse mure sono ingaggiate quando nessuna delle due è libera dietro all’altra. L’ingaggio decide chi si tiene discosta e chi ha diritto allo spazio alla boa.', 'Dois barcos na mesma amura estão sobrepostos quando nenhum está livre à ré do outro. Isso decide quem se mantém afastado e quem tem direito a espaço na marca.') },
    { id: 'clear-astern', group: 'right-of-way', term: t('Clear astern', 'Чисто позади', 'Libre por la popa', 'Klar achteraus', 'Açık arkada', 'Route libre derrière', 'Libera dietro', 'Livre à ré'), see: '/learn/rules#r12', def: t(
      'A boat is clear astern when her hull is behind a line square across the stern of the other boat. Clear astern keeps clear of clear ahead (rule 12).',
      'Лодка чисто позади, когда её корпус целиком за линией, проведённой поперёк через корму другой. Чисто позади уступает чисто впереди (правило 12).', 'Un barco está libre por la popa cuando su casco queda detrás de una línea perpendicular a la popa del otro barco. El libre por la popa se mantiene separado del libre por la proa (regla 12).', 'Ein Boot ist klar achteraus, wenn ihr Rumpf hinter einer Linie quer durch das Heck des anderen Bootes liegt. Klar achteraus hält sich von klar voraus frei (Regel 12).', 'Bir teknenin gövdesi, diğer teknenin kıçını enine kesen bir çizginin gerisindeyse açık arkadadır. Açık arkadaki, açık öndekinden uzak durur (kural 12).', 'Un bateau est en route libre derrière quand sa coque est en arrière d’une ligne perpendiculaire passant par l’arrière de l’autre bateau. Route libre derrière se maintient à l’écart de route libre devant (règle 12).', 'Una barca è libera dietro quando il suo scafo è dietro una linea perpendicolare alla poppa dell’altra barca. La barca libera dietro si tiene discosta da quella libera avanti (regola 12).', 'Um barco está livre à ré quando o casco dele está atrás de uma linha perpendicular que passa pela popa do outro barco. Livre à ré se mantém afastado de livre à vante (regra 12).') },
    { id: 'luff', group: 'points-of-sail', term: t('Luff (to luff)', 'Приводиться', 'Orzar', 'Anluven (anluven)', 'Orsalamak', 'Lofer', 'Orza (orzare)', 'Orçar'), def: t(
      'To turn towards the wind. A leeward boat may luff a windward one, which has to answer (rules 11 and 16).',
      'Поворачивать к ветру. Подветренная лодка может приводиться, и наветренная должна отвечать (правила 11 и 16).', 'Girar hacia el viento. Un barco de sotavento puede orzar sobre uno de barlovento, que tiene que responder (reglas 11 y 16).', 'Zum Wind hin drehen. Ein Leeboot darf anluven, und das Luvboot muss darauf reagieren (Regeln 11 und 16).', 'Rüzgâra doğru dönmek. Rüzgâraltındaki tekne rüzgârüstündekine orsalayabilir; o da buna karşılık vermek zorundadır (kural 11 ve 16).', 'Tourner vers le vent. Un bateau sous le vent peut lofer un bateau au vent, qui doit répondre (règles 11 et 16).', 'Girare verso il vento. Una barca sottovento può orzare una barca sopravvento, che deve rispondere (regole 11 e 16).', 'Virar em direção ao vento. Um barco a sotavento pode orçar contra um barco a barlavento, que tem de responder (regras 11 e 16).') },
    { id: 'bear-away', group: 'points-of-sail', term: t('Bear away', 'Уваливаться', 'Arribar', 'Abfallen', 'Boşlamak', 'Abattre', 'Poggiare', 'Arribar'), def: t(
      'To turn away from the wind. Upwind a boat bears away a few degrees to build speed; at the windward mark she bears away onto the run.',
      'Поворачивать от ветра. На лавировке немного уваливаются, чтобы набрать скорость; у верхнего знака уваливаются на попутный курс.', 'Girar alejándose del viento. De ceñida un barco arriba unos grados para ganar velocidad; en la baliza de barlovento arriba hacia la empopada.', 'Vom Wind weg drehen. Am Wind fällt ein Boot ein paar Grad ab, um Fahrt aufzubauen; an der Luvtonne fällt es auf den Vorwindkurs ab.', 'Rüzgârdan uzağa dönmek. Orsada bir tekne hız toplamak için birkaç derece boşlar; rüzgârüstü şamandırasında pupaya boşlar.', 'S’écarter du vent. Au près, un bateau abat de quelques degrés pour prendre de la vitesse ; à la bouée au vent, il abat pour partir au vent arrière.', 'Allontanarsi dal vento. Di bolina una barca poggia di qualche grado per prendere velocità; alla boa di bolina poggia per andare in poppa.', 'Virar para longe do vento. Na orça, o barco arriba alguns graus para ganhar velocidade; na boia de barlavento, ele arriba para a popa.') },
    { id: 'proper-course', group: 'right-of-way', term: t('Proper course', 'Надлежащий курс', 'Rumbo debido', 'Richtiger Kurs', 'Uygun rota', 'Route normale', 'Rotta propria', 'Rumo devido'), see: '/learn/rules#r11', def: t(
      'The course a boat would sail to finish as soon as possible if the other boats weren’t there. Some rules stop a boat sailing above it (rule 17).',
      'Курс, которым лодка шла бы, чтобы финишировать как можно скорее, если бы других лодок не было. Некоторые правила запрещают идти выше него (правило 17).', 'El rumbo que un barco navegaría para llegar lo antes posible si los otros barcos no estuvieran. Algunas reglas impiden a un barco navegar por encima de él (regla 17).', 'Der Kurs, den ein Boot segeln würde, um so schnell wie möglich ins Ziel zu kommen, wenn die anderen Boote nicht da wären. Einige Regeln hindern ein Boot daran, höher als er zu segeln (Regel 17).', 'Diğer tekneler olmasa bir teknenin mümkün olan en kısa sürede bitirmek için gideceği rota. Bazı kurallar teknenin bundan daha yükseğe yelken açmasını engeller (kural 17).', 'La route qu’un bateau suivrait pour finir le plus tôt possible si les autres bateaux n’étaient pas là. Certaines règles interdisent à un bateau de naviguer au-dessus (règle 17).', 'La rotta che una barca seguirebbe per arrivare il prima possibile se le altre barche non ci fossero. Alcune regole vietano a una barca di navigare al di sopra di essa (regola 17).', 'O rumo que um barco velejaria para terminar o mais cedo possível se os outros barcos não estivessem ali. Algumas regras impedem um barco de velejar acima dele (regra 17).') },
    { id: 'in-irons', group: 'points-of-sail', term: t('In irons', 'В левентике', 'Proa al viento', 'Im Wind stehen', 'Rüzgâra dikilmek', 'Bout au vent', 'Nell’angolo morto', 'Aproado'), def: t(
      'Stopped head to wind, with the sails flapping and no way to steer. Bear away until the sails fill again.',
      'Лодка встала носом к ветру, паруса полощут, рулём не управляется. Нужно уваливаться, пока паруса снова не наполнятся.', 'Parado proa al viento, con las velas aleteando y sin poder gobernar. Arriba hasta que las velas se llenen otra vez.', 'Mit dem Bug im Wind gestoppt, die Segel flattern und das Boot ist nicht steuerbar. Falle ab, bis die Segel wieder füllen.', 'Burnu rüzgâra dönük durmak; yelkenler çırpınır ve dümen tutmak mümkün olmaz. Yelkenler yeniden dolana kadar boşla.', 'Arrêté face au vent, les voiles qui faseyent et sans moyen de barrer. Abats jusqu’à ce que les voiles se remplissent à nouveau.', 'Ferma prua al vento, con le vele che sbattono e senza modo di governare. Poggia finché le vele non si riempiono di nuovo.', 'Parado de proa ao vento, com as velas panejando e sem governo. Arribe até as velas encherem de novo.') },
    { id: 'heel', group: 'points-of-sail', term: t('Heel', 'Крен', 'Escora', 'Krängung', 'Yatma', 'Gîte', 'Sbandamento', 'Adernamento'), see: '/learn/trim#heel', def: t(
      'How far the boat leans over with the wind in her sails. A little is right; too much and she slows, slips sideways and gets hard to steer, so ease the sheet or hike out.',
      'Насколько лодка накренилась под ветром в парусах. Немного — правильно; слишком много — и она теряет ход, её сносит и трудно держать на курсе: потравите шкот или откренивайте.', 'Lo que el barco se inclina con el viento en las velas. Un poco está bien; demasiado y pierde velocidad, abate y cuesta gobernarlo, así que suelta escota o saca el peso fuera.', 'Wie weit sich das Boot mit dem Wind in den Segeln zur Seite legt. Ein wenig ist richtig; zu viel, und es wird langsamer, macht Abdrift und lässt sich schwer steuern, also fier die Schot oder lehn dich hinaus.', 'Teknenin yelkenlerdeki rüzgârla ne kadar yana yattığı. Biraz yatması doğrudur; fazlası yavaşlatır, düşmeyi artırır ve dümeni zorlaştırır: iskotayı laçka et ya da rüzgârüstüne otur.', 'Ce que le bateau penche sous le vent dans ses voiles. Un peu, c’est bien ; trop, et il ralentit, dérive et devient dur à barrer : choque l’écoute ou fais du rappel.', 'Quanto la barca si inclina con il vento nelle vele. Un po’ va bene; troppo e rallenta, scarroccia e diventa dura da governare: lasca la scotta o fai contrappeso.', 'Quanto o barco se inclina com o vento nas velas. Um pouco é certo; demais e ele perde velocidade, abate e fica difícil de governar: solte a escota ou faça contrapeso.') },
    { id: 'apparent-wind', group: 'points-of-sail', term: t('True and apparent wind', 'Истинный и вымпельный ветер', 'Viento real y aparente', 'Wahrer und scheinbarer Wind', 'Gerçek ve görünür rüzgâr', 'Vent réel et vent apparent', 'Vento reale e apparente', 'Vento real e aparente'), see: '/learn/sail#apparent', def: t(
      'The true wind is the wind as it blows over the water; the apparent wind is what the moving boat feels, the true wind plus the wind of her own speed. It comes from further ahead, and it is what the sails are trimmed to.',
      'Истинный ветер — ветер, который дует над водой; вымпельный — тот, что чувствует идущая лодка: истинный плюс встречный ветер от её собственного хода. Он дует острее, и паруса настраивают по нему.', 'El viento real es el que sopla sobre el agua; el aparente es el que siente el barco en marcha, el real más el viento de su propia velocidad. Viene de más proa, y es el que se usa para trimar las velas.', 'Der wahre Wind ist der Wind, wie er über das Wasser weht; der scheinbare ist der, den das fahrende Boot spürt: der wahre plus der Fahrtwind. Er kommt weiter von vorn, und nach ihm werden die Segel getrimmt.', 'Gerçek rüzgâr suyun üzerinde esen rüzgârdır; görünür rüzgâr ise ilerleyen teknenin hissettiği rüzgârdır: gerçek rüzgâr artı kendi hızının yarattığı rüzgâr. Daha baş taraftan gelir ve yelkenler ona göre trimlenir.', 'Le vent réel est celui qui souffle sur l’eau ; le vent apparent est celui que ressent le bateau en marche : le vent réel plus le vent de sa propre vitesse. Il vient de plus en avant, et c’est sur lui qu’on règle les voiles.', 'Il vento reale è quello che soffia sull’acqua; il vento apparente è quello che sente la barca in movimento: il reale più il vento della sua stessa velocità. Arriva più da prua, ed è su di lui che si regolano le vele.', 'O vento real é o que sopra sobre a água; o aparente é o que o barco em movimento sente: o real mais o vento da sua própria velocidade. Vem mais de proa, e é por ele que as velas são reguladas.') },
    { id: 'vmg', group: 'points-of-sail', term: t('VMG (velocity made good)', 'VMG (скорость к цели)', 'VMG (velocidad hacia el objetivo)', 'VMG (Geschwindigkeit zum Ziel)', 'VMG (hedefe hız)', 'VMG (vitesse vers l’objectif)', 'VMG (velocità verso l’obiettivo)', 'VMG (velocidade rumo ao objetivo)'), see: '/learn/downwind#angles', def: t(
      'How fast the boat is getting towards where she is going, upwind or downwind, rather than through the water. Upwind and downwind she sails at an angle, and the best angle is the one with the best VMG.',
      'Как быстро лодка приближается к цели — вверх или вниз по ветру, — а не как быстро идёт по воде. На лавировке и попутных курсах она идёт под углом, и лучший угол — тот, что даёт наибольшую VMG.', 'Lo rápido que el barco avanza hacia donde va, a barlovento o a sotavento, y no a través del agua. Ciñendo y en popa navega en ángulo, y el mejor ángulo es el de mejor VMG.', 'Wie schnell das Boot dorthin vorankommt, wo es hinwill, nach Luv oder nach Lee, und nicht durchs Wasser. Am Wind und vor dem Wind segelt es im Winkel, und der beste Winkel ist der mit der besten VMG.', 'Teknenin suda değil, gittiği yöne, rüzgârüstüne ya da rüzgâraltına ne kadar hızlı ilerlediği. Orsada ve pupada açıyla seyreder; en iyi açı, en iyi VMG’yi veren açıdır.', 'La vitesse à laquelle le bateau se rapproche de là où il va, au vent ou sous le vent, et non sa vitesse sur l’eau. Au près et au portant il navigue en angle, et le meilleur angle est celui qui donne la meilleure VMG.', 'Quanto in fretta la barca si avvicina a dove sta andando, sopravvento o sottovento, e non quanto va veloce sull’acqua. Di bolina e in poppa naviga ad angolo, e l’angolo migliore è quello con la VMG migliore.', 'A rapidez com que o barco avança rumo ao seu destino, a barlavento ou a sotavento, e não pela água. Na orça e na popa ele veleja em ângulo, e o melhor ângulo é o de melhor VMG.') },
    { id: 'header', group: 'wind', term: t('Header', 'Заход ветра', 'Rolada desfavorable', 'Dreher', 'Aleyhte dönüş', 'Refus', 'Salto a scarso', 'Rondada contra'), see: '/learn/shifts', def: t(
      'A wind shift that comes from further ahead, so a close-hauled boat has to bear away. Upwind, tack on the headers.',
      'Сдвиг ветра к носу, из-за которого лодке в бейдевинд приходится уваливаться. На лавировке поворачивай на заходе.', 'Un cambio de viento que viene de más a proa, de modo que un barco de ceñida tiene que arribar. De ceñida, vira en las roladas desfavorables.', 'Ein Winddreher, der von weiter vorn kommt, sodass ein Boot hoch am Wind abfallen muss. Am Wind wende auf den Drehern.', 'Daha ilerden gelen bir rüzgâr dönüşü; orsadaki tekne boşlamak zorunda kalır. Orsada aleyhte dönüşlerde tramola at.', 'Une bascule de vent qui vient plus de l’avant, si bien qu’un bateau au près doit abattre. Au près, vire sur les refus.', 'Un salto di vento che arriva più da prua, così una barca di bolina deve poggiare. Di bolina, vira sui salti a scarso.', 'Uma rondada de vento que vem mais de proa, de modo que um barco na orça precisa arribar. Na orça, cambe nas rondadas contra.') },
    { id: 'lift', group: 'wind', term: t('Lift', 'Отход ветра', 'Rolada favorable', 'Raumer', 'Lehte dönüş', 'Adonnante', 'Salto a buono', 'Rondada a favor'), see: '/learn/shifts', def: t(
      'A wind shift that comes from further aft, so a close-hauled boat can point higher. A header on one tack is a lift on the other.',
      'Сдвиг ветра к корме, при котором лодка в бейдевинд может идти круче. Заход на одном галсе — отход на другом.', 'Un cambio de viento que viene de más a popa, de modo que un barco de ceñida puede apuntar más alto. Una rolada desfavorable en una amura es favorable en la otra.', 'Ein Winddreher, der von weiter achtern kommt, sodass ein Boot hoch am Wind höher fahren kann. Ein Dreher auf dem einen Bug ist ein Raumer auf dem anderen.', 'Daha geriden gelen bir rüzgâr dönüşü; orsadaki tekne daha yükseğe dümen tutabilir. Bir kontradaki aleyhte dönüş, öbüründe lehte dönüştür.', 'Une bascule de vent qui vient plus de l’arrière, si bien qu’un bateau au près peut serrer davantage le vent. Un refus sur un bord est une adonnante sur l’autre.', 'Un salto di vento che arriva più da poppa, così una barca di bolina può stringere di più. Un salto a scarso su una mura è un salto a buono sull’altra.', 'Uma rondada de vento que vem mais de trás, de modo que um barco na orça pode orçar mais. Uma rondada contra em uma amura é uma rondada a favor na outra.') },
    { id: 'veer-back', group: 'wind', term: t('Veer and back', 'Сдвиг ветра вправо и влево', 'Rolada a la derecha y a la izquierda', 'Rechtsdreher und Linksdreher', 'Sağa ve sola dönüş', 'Bascule à droite et à gauche', 'Rotazione a destra e a sinistra', 'Rondada à direita e à esquerda'), see: '/learn/shifts#what', def: t(
      'The wind veers when it shifts clockwise, coming from further right, and backs when it shifts anticlockwise. The race’s wind readout shows which way it has gone.',
      'Ветер сдвигается вправо, когда поворачивает по часовой стрелке и начинает дуть правее, и влево — когда против часовой. В гонке это видно по показаниям ветра на экране.', 'El viento rola a la derecha cuando gira en el sentido de las agujas del reloj y viene de más a la derecha, y a la izquierda cuando gira al revés. En la regata, el indicador del viento muestra hacia dónde ha rolado.', 'Der Wind dreht rechts, wenn er im Uhrzeigersinn dreht und weiter von rechts kommt, und links, wenn er gegen den Uhrzeigersinn dreht. Im Rennen zeigt die Windanzeige, wohin er gedreht hat.', 'Rüzgâr saat yönünde döndüğünde, yani daha sağdan esmeye başladığında sağa, saat yönünün tersine döndüğünde sola döner. Yarışta rüzgâr göstergesi hangi yöne döndüğünü gösterir.', 'Le vent bascule à droite quand il tourne dans le sens des aiguilles d’une montre et vient de plus à droite, et à gauche dans l’autre sens. Pendant la régate, l’affichage du vent indique de quel côté il a tourné.', 'Il vento ruota a destra quando gira in senso orario e arriva più da destra, e a sinistra quando gira in senso antiorario. In regata l’indicatore del vento mostra da che parte ha girato.', 'O vento ronda para a direita quando gira no sentido horário e passa a vir mais da direita, e para a esquerda quando gira no sentido anti-horário. Na regata, o mostrador do vento indica para que lado rondou.') },
    { id: 'oscillating', group: 'wind', term: t('Oscillating shifts', 'Колебания ветра', 'Roladas oscilantes', 'Pendelnde Winddreher', 'Salınan rüzgâr dönüşleri', 'Bascules oscillantes', 'Salti di vento oscillanti', 'Rondadas oscilantes'), see: '/learn/shifts#tack', def: t(
      'The wind swinging back and forth either side of its mean direction every few minutes. Tack on each header and you sail the lifts all the way up the beat.',
      'Ветер раскачивается то в одну, то в другую сторону от среднего направления каждые несколько минут. Поворачивайте на каждом заходе — и всю лавировку будете идти на отходах.', 'El viento que oscila a un lado y a otro de su dirección media cada pocos minutos. Vira en cada rolada desfavorable y harás toda la ceñida con roladas favorables.', 'Der Wind, der alle paar Minuten um seine mittlere Richtung hin und her pendelt. Wende bei jedem Dreher, und du segelst die ganze Kreuz über auf Raumern.', 'Rüzgârın birkaç dakikada bir ortalama yönünün iki yanına gidip gelmesi. Her aleyhte dönüşte tramola at; böylece orsa ayağının tamamını lehte dönüşlerle çıkarsın.', 'Le vent qui oscille de part et d’autre de sa direction moyenne toutes les quelques minutes. Vire sur chaque refus et tu remontes tout le bord de près dans les adonnantes.', 'Il vento che oscilla avanti e indietro attorno alla sua direzione media ogni pochi minuti. Vira su ogni salto a scarso e farai tutta la bolina con i salti a buono.', 'O vento que oscila para um lado e para o outro da sua direção média a cada poucos minutos. Cambe em cada rondada contra e você faz toda a orça nas rondadas a favor.') },
    { id: 'persistent', group: 'wind', term: t('Persistent shift', 'Устойчивый сдвиг ветра', 'Rolada persistente', 'Dauerhafter Dreher', 'Kalıcı dönüş', 'Bascule persistante', 'Salto persistente', 'Rondada persistente'), see: '/learn/shifts#dont', def: t(
      'A shift that keeps going one way and doesn’t come back. Sail towards it first, to the side the new wind comes from, rather than tacking on every header.',
      'Сдвиг ветра, который продолжается в одну сторону и не возвращается. Сначала идите в ту сторону, откуда будет дуть новый ветер, а не поворачивайте на каждом заходе.', 'Una rolada que sigue hacia un lado y no vuelve. Navega primero hacia ella, hacia el lado de donde vendrá el nuevo viento, en lugar de virar en cada rolada desfavorable.', 'Ein Dreher, der immer weiter in eine Richtung geht und nicht zurückkommt. Segle zuerst zu ihm hin, auf die Seite, von der der neue Wind kommt, statt bei jedem Dreher zu wenden.', 'Hep bir yöne devam eden ve geri dönmeyen rüzgâr dönüşü. Her aleyhte dönüşte tramola atmak yerine önce ona, yeni rüzgârın geleceği tarafa doğru seyret.', 'Une bascule qui continue dans un sens et ne revient pas. Va d’abord vers elle, du côté d’où viendra le nouveau vent, au lieu de virer sur chaque refus.', 'Un salto di vento che continua in una direzione e non torna indietro. Vai prima verso di esso, dal lato da cui arriverà il vento nuovo, invece di virare su ogni salto a scarso.', 'Uma rondada que continua para um lado e não volta. Veleje primeiro em direção a ela, para o lado de onde virá o vento novo, em vez de cambar a cada rondada contra.') },
    { id: 'layline', group: 'wind', term: t('Layline', 'Лейлайн', 'Layline', 'Layline', 'Layline', 'Lay-line', 'Layline', 'Layline'), see: '/learn/shifts#lay', def: t(
      'The line from which a boat can just fetch the mark on one tack, without another tack. Reach it too early and every shift works against you.',
      'Линия, с которой знак берётся одним галсом, без лишнего поворота. Выйдешь на неё слишком рано — любой сдвиг ветра против тебя.', 'La línea desde la que un barco puede justo alcanzar la baliza en una amura, sin otra virada. Si la alcanzas demasiado pronto, cada rolada juega en tu contra.', 'Die Linie, von der aus ein Boot die Bahnmarke auf einem Bug gerade noch anliegen kann, ohne eine weitere Wende. Erreichst du sie zu früh, arbeitet jeder Winddreher gegen dich.', 'Bir teknenin şamandırayı başka tramola atmadan, tek kontradan tam tutabileceği çizgi. Ona çok erken varırsan her rüzgâr dönüşü sana karşı çalışır.', 'La ligne à partir de laquelle un bateau peut tout juste atteindre la bouée sur un seul bord, sans virer à nouveau. Atteins-la trop tôt et chaque bascule joue contre toi.', 'La linea da cui una barca riesce appena a prendere la boa con una sola mura, senza un’altra virata. Raggiungila troppo presto e ogni salto di vento gioca contro di te.', 'A linha a partir da qual um barco consegue chegar exatamente à boia em uma só amura, sem outra cambada. Chegue nela cedo demais e cada rondada joga contra você.') },
    { id: 'dirty-air', group: 'wind', term: t('Dirty air', 'Ветровая тень', 'Aire sucio', 'Abwind', 'Kirli hava', 'Vent perturbé', 'Aria sporca', 'Vento sujo'), see: '/learn/start#air', def: t(
      'The weaker, bent wind behind and to leeward of another boat’s sails. A boat in it is slower, so she tacks away to clear air.',
      'Ослабленный и сбитый ветер за парусами другой лодки и под ветром от неё. В тени лодка идёт медленнее, поэтому поворачивает в чистый ветер.', 'El viento más débil y desviado detrás y a sotavento de las velas de otro barco. Un barco metido en él va más lento, así que vira para buscar aire limpio.', 'Der schwächere, abgelenkte Wind hinter und in Lee der Segel eines anderen Bootes. Ein Boot darin ist langsamer, also wendet es weg in klaren Wind.', 'Başka bir teknenin yelkenlerinin arkasındaki ve rüzgâraltındaki daha zayıf, bükülmüş rüzgâr. İçindeki tekne daha yavaştır; bu yüzden temiz rüzgâra tramola atar.', 'Le vent plus faible et dévié derrière et sous le vent des voiles d’un autre bateau. Un bateau qui s’y trouve est plus lent, alors il vire pour retrouver de l’air pur.', 'Il vento più debole e deviato dietro e sottovento alle vele di un’altra barca. Una barca che ci si trova è più lenta, così vira per cercare aria pulita.', 'O vento mais fraco e desviado atrás e a sotavento das velas de outro barco. Um barco nele fica mais lento, então camba para buscar vento limpo.') },
    { id: 'gust', group: 'wind', term: t('Gust and lull', 'Порыв и затишье', 'Racha y calma', 'Bö und Flaute', 'Rüzgâr hamlesi ve durgunluk', 'Risée et molle', 'Raffica e calo', 'Rajada e buraco de vento'), see: '/learn/shifts#gusts', def: t(
      'A gust is a patch of stronger wind, darker on the water; a lull is a patch of lighter wind.',
      'Порыв — участок более сильного ветра, на воде темнее; затишье — участок более слабого.', 'Una racha es una zona de viento más fuerte, más oscura sobre el agua; una calma es una zona de viento más flojo.', 'Eine Bö ist ein Fleck stärkeren Windes, dunkler auf dem Wasser; eine Flaute ist ein Fleck schwächeren Windes.', 'Rüzgâr hamlesi, sudan daha koyu görünen daha güçlü rüzgâr yamasıdır; durgunluk, daha hafif rüzgâr yamasıdır.', 'Une risée est une zone de vent plus fort, plus sombre sur l’eau ; une molle est une zone de vent plus faible.', 'Una raffica è una chiazza di vento più forte, più scura sull’acqua; un calo è una chiazza di vento più leggero.', 'Uma rajada é uma mancha de vento mais forte, mais escura na água; um buraco de vento é uma mancha de vento mais fraco.') },
    { id: 'current', group: 'wind', term: t('Current (tide)', 'Течение', 'Corriente', 'Strömung', 'Akıntı', 'Courant', 'Corrente', 'Corrente'), def: t(
      'The water itself moving, carrying every boat with it. Against it a boat takes longer to reach a mark; at a mark it sets her towards it or away from it.',
      'Движение самой воды, которое несёт с собой каждую лодку. Против течения до знака идти дольше; у знака оно сносит лодку на знак или от него.', 'El agua misma en movimiento, que arrastra a todos los barcos. En contra, un barco tarda más en llegar a una baliza; junto a una baliza lo empuja hacia ella o lo aleja.', 'Das Wasser selbst in Bewegung, das jedes Boot mitnimmt. Dagegen braucht ein Boot länger zur Tonne; an einer Tonne versetzt es das Boot auf sie zu oder von ihr weg.', 'Suyun kendisinin hareketi; her tekneyi beraberinde taşır. Akıntıya karşı bir tekne şamandıraya daha geç varır; şamandıranın yanında tekneyi ona doğru ya da ondan uzağa sürükler.', 'L’eau elle-même en mouvement, qui emporte chaque bateau. Contre lui, un bateau met plus de temps à atteindre une bouée ; près d’une bouée, il le porte vers elle ou l’en écarte.', 'L’acqua stessa in movimento, che porta con sé ogni barca. Contro corrente una barca impiega di più a raggiungere una boa; vicino a una boa la spinge verso di essa o lontano.', 'A própria água em movimento, levando cada barco com ela. Contra a corrente um barco demora mais a chegar a uma boia; junto a uma boia ela empurra o barco para ela ou para longe.') },
    { id: 'start-line', group: 'start', term: t('Start line', 'Стартовая линия', 'Línea de salida', 'Startlinie', 'Start hattı', 'Ligne de départ', 'Linea di partenza', 'Linha de largada'), see: '/learn/start', def: t(
      'The line between the committee boat and the pin, a mark at the other end. Boats start when they cross it after the starting signal.',
      'Линия между судейским судном и знаком на другом её конце. Лодки стартуют, пересекая её после стартового сигнала.', 'La línea entre el barco del comité y el pin, una baliza en el otro extremo. Los barcos salen al cruzarla tras la señal de salida.', 'Die Linie zwischen dem Wettfahrtleitungsboot und dem Pin, einer Marke am anderen Ende. Boote starten, wenn sie sie nach dem Startsignal überqueren.', 'Komite teknesi ile öbür uçtaki bir şamandıra olan pin arasındaki hat. Tekneler start işaretinden sonra hattı geçtiklerinde start eder.', 'La ligne entre le bateau comité et la bouée viseur, une bouée à l’autre extrémité. Les bateaux prennent le départ quand ils la franchissent après le signal de départ.', 'La linea tra la barca comitato e la boa di partenza, all’altra estremità. Le barche partono quando la tagliano dopo il segnale di partenza.', 'A linha entre o barco da comissão de regata e a boia de largada, uma boia na outra extremidade. Os barcos largam quando a cruzam depois do sinal de largada.') },
    { id: 'committee-boat', group: 'start', term: t('Committee boat', 'Судейское судно', 'Barco del comité', 'Startschiff', 'Komite teknesi', 'Bateau comité', 'Barca giuria', 'Barco da comissão'), see: '/learn/start#flags', def: t(
      'The race officers’ boat at the starboard end of the start line. It flies the flags and sounds the signals, and it is part of the line: no boat may touch it.',
      'Судно гоночного комитета на правом конце стартовой линии. На нём поднимают флаги и подают сигналы, и оно — часть линии: касаться его нельзя.', 'El barco de los oficiales de regata en el extremo de estribor de la línea de salida. Iza las banderas y da las señales, y forma parte de la línea: ningún barco puede tocarlo.', 'Das Schiff der Wettfahrtleitung am Steuerbordende der Startlinie. Es setzt die Flaggen und gibt die Signale, und es gehört zur Linie: kein Boot darf es berühren.', 'Start hattının sancak ucundaki yarış görevlilerinin teknesi. Bayrakları çeker, işaretleri verir ve hattın parçasıdır: hiçbir tekne ona dokunamaz.', 'Le bateau des officiels de course, à l’extrémité tribord de la ligne de départ. Il envoie les pavillons et les signaux sonores, et il fait partie de la ligne : aucun bateau ne doit le toucher.', 'La barca dei giudici di regata all’estremità di dritta della linea di partenza. Issa le bandiere e dà i segnali, e fa parte della linea: nessuna barca può toccarla.', 'O barco dos oficiais de regata na ponta de boreste da linha de largada. Ele iça as bandeiras e dá os sinais, e faz parte da linha: nenhum barco pode tocá-lo.') },
    { id: 'pin', group: 'start', term: t('Pin end', 'Пин (левый конец линии)', 'Lado baliza', 'Pin-Ende', 'Pin ucu', 'Côté bouée', 'Lato boa', 'Lado da boia'), see: '/learn/start#end', def: t(
      'The buoy at the port end of the start line, and that end of the line. When it lies further upwind than the committee boat, the line favours a start there.',
      'Буй на левом конце стартовой линии и сам этот конец. Если он ближе к ветру, чем судейское судно, выгоднее стартовать у него.', 'La boya del extremo de babor de la línea de salida, y ese extremo de la línea. Cuando queda más a barlovento que el barco del comité, la línea favorece salir por ahí.', 'Die Boje am Backbordende der Startlinie und dieses Ende der Linie. Liegt sie weiter in Luv als das Startschiff, ist ein Start dort begünstigt.', 'Start hattının iskele ucundaki şamandıra ve hattın o ucu. Komite teknesinden daha rüzgârüstünde kalıyorsa, oradan start almak avantajlıdır.', 'La bouée à l’extrémité bâbord de la ligne de départ, et ce bout de la ligne. Quand elle est plus au vent que le bateau comité, la ligne favorise un départ de ce côté.', 'La boa all’estremità di sinistra della linea di partenza, e quel lato della linea. Quando è più sopravvento della barca giuria, conviene partire lì.', 'A boia na ponta de bombordo da linha de largada, e essa ponta da linha. Quando ela fica mais a barlavento que o barco da comissão, a linha favorece largar por ali.') },
    { id: 'starting-signal', group: 'start', term: t('Starting signal', 'Стартовый сигнал', 'Señal de salida', 'Startsignal', 'Start işareti', 'Signal de départ', 'Segnale di partenza', 'Sinal de largada'), see: '/learn/start#flags', def: t(
      'The gun, or the horn, and the class flag coming down: the moment boats may cross the line and start. Four minutes before, the preparatory flag goes up, and one minute before it comes down.',
      'Выстрел или гудок и спуск флага класса: момент, когда лодки могут пересекать линию и стартовать. За четыре минуты поднимают подготовительный флаг, за минуту его спускают.', 'El cañonazo o la bocina, y la bandera de clase que baja: el momento en que los barcos pueden cruzar la línea y salir. Cuatro minutos antes se iza la bandera de preparación, y un minuto antes se arría.', 'Der Schuss oder das Horn, und die Klassenflagge geht nieder: der Moment, ab dem die Boote die Linie überqueren und starten dürfen. Vier Minuten vorher wird die Vorbereitungsflagge gesetzt, eine Minute vorher niedergeholt.', 'Top ya da korna sesi ve sınıf bayrağının inmesi: teknelerin hattı geçip start alabildiği an. Dört dakika önce hazırlık bayrağı çekilir, bir dakika önce indirilir.', 'Le coup de canon, ou de corne, et le pavillon de classe qui descend : le moment où les bateaux peuvent couper la ligne et partir. Quatre minutes avant, le pavillon préparatoire est envoyé, et une minute avant il est amené.', 'Il colpo di cannone, o la tromba, e la bandiera di classe che scende: il momento in cui le barche possono tagliare la linea e partire. Quattro minuti prima si issa la bandiera preparatoria, e un minuto prima la si ammaina.', 'O tiro, ou a buzina, e a bandeira da classe arriada: o momento em que os barcos podem cruzar a linha e largar. Quatro minutos antes a bandeira preparatória é içada, e um minuto antes é arriada.') },
    { id: 'favoured-end', group: 'start', term: t('Favoured end', 'Выгодный конец линии', 'Extremo favorecido', 'Begünstigtes Ende', 'Avantajlı uç', 'Extrémité favorisée', 'Estremità favorita', 'Lado favorecido'), see: '/learn/start#end', def: t(
      'The end of the start line further upwind. A boat that starts there is ahead of one that starts at the other end.',
      'Конец стартовой линии, который ближе к ветру. Лодка, стартовавшая там, впереди той, что ушла с другого конца.', 'El extremo de la línea de salida más a barlovento. Un barco que sale por allí va por delante de uno que sale por el otro extremo.', 'Das Ende der Startlinie weiter in Luv. Ein Boot, das dort startet, liegt vor einem, das am anderen Ende startet.', 'Start hattının rüzgâra daha yakın ucu. Orada start eden tekne, öbür uçta start edenin önündedir.', 'L’extrémité de la ligne de départ la plus au vent. Un bateau qui part de là est devant celui qui part de l’autre extrémité.', 'L’estremità della linea di partenza più sopravvento. Una barca che parte lì è davanti a una che parte all’altra estremità.', 'A extremidade da linha de largada que fica mais a barlavento. Um barco que larga ali está à frente de um que larga na outra extremidade.') },
    { id: 'line-bias', group: 'start', term: t('Line bias', 'Перекос линии', 'Sesgo de línea', 'Linienvorteil', 'Hat avantajı', 'Biais de la ligne', 'Favore della linea', 'Linha favorecida'), see: '/learn/start#end', def: t(
      'How far the start line is turned from square to the wind, in degrees. The more bias, the further one end lies upwind of the other; the race shows it, and which end it favours, before the gun.',
      'На сколько градусов стартовая линия развёрнута от перпендикуляра к ветру. Чем больше перекос, тем выше по ветру один конец, чем другой; гонка показывает его и выгодный конец до старта.', 'Cuántos grados está girada la línea de salida respecto a la perpendicular al viento. Cuanto más sesgo, más a barlovento queda un extremo del otro; la regata lo muestra, y qué extremo favorece, antes de la salida.', 'Um wie viel Grad die Startlinie gegen die Senkrechte zum Wind gedreht ist. Je größer der Vorteil, desto weiter liegt ein Ende in Luv des anderen; das Rennen zeigt ihn vor dem Start an, und welches Ende er begünstigt.', 'Start hattının rüzgâra dik konumdan kaç derece döndüğü. Avantaj ne kadar büyükse bir uç ötekinden o kadar rüzgârüstündedir; yarış bunu ve hangi ucun avantajlı olduğunu starttan önce gösterir.', 'De combien de degrés la ligne de départ est tournée par rapport à la perpendiculaire au vent. Plus le biais est grand, plus un bout est au vent de l’autre ; la régate l’affiche avant le départ, avec le côté qu’il favorise.', 'Di quanti gradi la linea di partenza è ruotata rispetto alla perpendicolare al vento. Più è grande, più un’estremità è sopravvento all’altra; la regata lo mostra prima della partenza, con l’estremità favorita.', 'Quantos graus a linha de largada está girada em relação à perpendicular ao vento. Quanto maior, mais uma ponta fica a barlavento da outra; a regata mostra isso antes da largada, e qual ponta é favorecida.') },
    { id: 'ocs', group: 'start', term: t('OCS (over early)', 'Фальстарт (OCS)', 'OCS (salir antes de tiempo)', 'OCS (zu früh über der Linie)', 'OCS (erken geçmek)', 'OCS (parti trop tôt)', 'OCS (partito in anticipo)', 'OCS (largada queimada)'), see: '/learn/start#early', def: t(
      'On the course side of the start line at the starting signal. Under the P flag the boat goes back and starts again; the committee flies X.',
      'Лодка оказалась на стороне дистанции от стартовой линии в момент сигнала. Под флагом P она возвращается и стартует заново; комитет поднимает флаг X.', 'Estar en el lado del recorrido de la línea de salida en la señal de salida. Con la bandera P el barco vuelve y sale de nuevo; el comité iza la X.', 'Beim Startsignal auf der Bahnseite der Startlinie. Unter der P-Flagge fährt das Boot zurück und startet erneut; die Wettfahrtleitung setzt X.', 'Start işaretinde start hattının parkur tarafında olmak. P bayrağı altında tekne geri dönüp yeniden start eder; komite X bayrağı çeker.', 'Du côté du parcours de la ligne de départ au signal de départ. Sous le pavillon P, le bateau revient et reprend le départ ; le comité envoie le pavillon X.', 'Dalla parte del percorso rispetto alla linea di partenza al segnale di partenza. Con la bandiera P la barca torna indietro e riparte; il comitato espone la X.', 'Do lado do percurso da linha de largada no sinal de largada. Com a bandeira P, o barco volta e larga de novo; a comissão iça a bandeira X.') },
    { id: 'general-recall', group: 'start', term: t('General recall', 'Общий отзыв', 'Llamada general', 'Allgemeiner Rückruf', 'Genel geri çağırma', 'Rappel général', 'Richiamo generale', 'Chamada geral'), see: '/learn/start#early', def: t(
      'The whole start is called off, usually because too many boats were over early to identify, and the fleet starts again.',
      'Отзыв всего флота со старта, обычно потому, что слишком много лодок оказались за линией, и флот стартует заново.', 'Se anula toda la salida, normalmente porque demasiados barcos salieron antes de tiempo para identificarlos, y la flota sale otra vez.', 'Der ganze Start wird zurückgerufen, meist weil zu viele Boote zu früh über der Linie waren, um sie zu erkennen, und das Feld startet erneut.', 'Bütün start iptal edilir, genelde tanımlanamayacak kadar çok tekne erken geçtiği için, ve filo yeniden start eder.', 'Tout le départ est annulé, en général parce que trop de bateaux étaient partis trop tôt pour être identifiés, et la flotte reprend le départ.', 'L’intera partenza viene annullata, di solito perché troppe barche erano partite in anticipo per poterle identificare, e la flotta riparte.', 'A largada inteira é anulada (chamada geral), em geral porque havia barcos demais queimando a largada para identificar todos, e a flotilha larga de novo.') },
    { id: 'leg', group: 'marks', term: t('Leg', 'Отрезок', 'Tramo', 'Schenkel', 'Ayak', 'Bord', 'Lato', 'Perna'), def: t(
      'One stretch of the course, from one mark to the next: a beat up to the windward mark, a run down to the gate, a reach out to the wing mark.',
      'Часть дистанции от одного знака до следующего: лавировка к верхнему знаку, попутный курс к нижним воротам, галфвинд к боковому знаку.', 'Un trozo del recorrido, de una baliza a la siguiente: una ceñida hasta la baliza de barlovento, una popa hasta la puerta, un través hasta la baliza de través.', 'Ein Abschnitt des Kurses, von einer Tonne zur nächsten: eine Kreuz zur Luvtonne, ein Vorwindkurs zum Leetor, ein Raumschotskurs zur Raumtonne.', 'Parkurun bir şamandıradan ötekine uzanan bir bölümü: rüzgârüstü şamandırasına orsa ayağı, kapıya pupa, kanat şamandırasına apaz.', 'Une portion du parcours, d’une bouée à la suivante : un bord de près jusqu’à la bouée au vent, un vent arrière jusqu’à la porte, un largue jusqu’à la bouée de largue.', 'Un tratto del percorso, da una boa alla successiva: una bolina fino alla boa di bolina, una poppa fino al cancello, un lasco fino alla boa di lasco.', 'Um trecho do percurso, de uma boia à seguinte: uma orça até a boia de barlavento, uma popa até o portão, um través até a boia de través.') },
    { id: 'windward-mark', group: 'marks', term: t('Windward mark', 'Верхний знак', 'Baliza de barlovento', 'Luvtonne', 'Rüzgârüstü şamandırası', 'Bouée au vent', 'Boa di bolina', 'Boia de barlavento'), see: '/learn/marks', def: t(
      'The mark at the top of the beat, usually left to port.',
      'Знак в конце лавировки; обычно его оставляют слева.', 'La baliza al final de la ceñida, normalmente dejada por babor.', 'Die Marke am oberen Ende des Kreuzes, meist an Backbord gelassen.', 'Orsa ayağının tepesindeki şamandıra, genelde iskelede bırakılır.', 'La bouée en haut du bord de près, en général laissée à bâbord.', 'La boa in cima al lato di bolina, di solito da lasciare a sinistra.', 'A boia no topo da perna de orça, em geral deixada por bombordo.') },
    { id: 'offset-mark', group: 'marks', term: t('Offset mark', 'Отбойник', 'Baliza de desmarque', 'Ablauftonne', 'Ofset şamandırası', 'Bouée de dégagement', 'Boa di disimpegno', 'Boia de offset'), def: t(
      'A mark a short way to one side of the windward mark, rounded just after it, to spread the boats out before they bear away onto the run.',
      'Знак немного в стороне от верхнего, который огибают сразу после него, чтобы лодки разошлись, прежде чем увалиться на попутный курс.', 'Una baliza a poca distancia a un lado de la de barlovento, que se rodea justo después de ella para que los barcos se separen antes de arribar a la popa.', 'Eine Tonne ein kurzes Stück seitlich der Luvtonne, die direkt nach ihr gerundet wird, damit sich die Boote verteilen, bevor sie auf den Vorwindkurs abfallen.', 'Rüzgârüstü şamandırasının biraz yanındaki, hemen ondan sonra dönülen şamandıra; tekneler pupaya düşmeden önce açılsın diye konur.', 'Une bouée un peu sur le côté de la bouée au vent, contournée juste après elle, pour espacer les bateaux avant qu’ils abattent au vent arrière.', 'Una boa poco di lato a quella di bolina, girata subito dopo, perché le barche si distanzino prima di poggiare in poppa.', 'Uma boia um pouco ao lado da de barlavento, contornada logo depois dela, para espalhar os barcos antes de arribarem para a popa.') },
    { id: 'wing-mark', group: 'marks', term: t('Wing mark', 'Боковой знак', 'Baliza de través', 'Raumtonne', 'Kanat şamandırası', 'Bouée de largue', 'Boa di lasco', 'Boia de través'), def: t(
      'On a triangle course, the mark out to one side between the windward mark and the leeward one: a reach out to it, a gybe round it, and a reach back down.',
      'На треугольной дистанции — знак сбоку между верхним и нижним: к нему идут галфвиндом, огибают его поворотом фордевинд и идут обратно вниз бакштагом.', 'En un recorrido triangular, la baliza situada a un lado entre la de barlovento y la de sotavento: un través hasta ella, una trasluchada al rodearla y un largo de vuelta hacia abajo.', 'Auf einem Dreieckskurs die Tonne seitlich zwischen der Luv- und der Leetonne: ein Raumschotskurs hin, eine Halse um sie herum und ein Raumschotskurs zurück nach unten.', 'Üçgen parkurda rüzgârüstü ve rüzgâraltı şamandıraları arasında yanda duran şamandıra: ona apazla gidilir, kavançayla dönülür ve yine apazla aşağı inilir.', 'Sur un parcours triangle, la bouée sur le côté entre la bouée au vent et celle sous le vent : un largue pour y aller, un empannage pour la contourner, et un largue pour redescendre.', 'In un percorso a triangolo, la boa a lato tra quella di bolina e quella di poppa: un lasco per arrivarci, una strambata per girarla e un lasco per tornare giù.', 'Num percurso em triângulo, a boia de lado entre a de barlavento e a de sotavento: um través até ela, um jibe para contorná-la e um largo de volta para baixo.') },
    { id: 'gate', group: 'marks', term: t('Leeward gate', 'Нижние ворота', 'Puerta de sotavento', 'Leetor', 'Rüzgâraltı kapısı', 'Porte sous le vent', 'Cancello di poppa', 'Portão de sotavento'), see: '/learn/marks#gate', def: t(
      'Two marks at the bottom of the run. A boat sails between them and rounds either one, and starts the next beat from there.',
      'Два знака в конце попутного курса. Лодка проходит между ними, огибает любой и оттуда начинает следующую лавировку.', 'Dos balizas al final de la empopada. Un barco pasa entre ellas, redondea una cualquiera y empieza desde allí la siguiente ceñida.', 'Zwei Marken am unteren Ende des Vorwindkurses. Ein Boot segelt dazwischen hindurch und rundet eine von beiden, und startet von dort auf das nächste Kreuz.', 'Pupa ayağının altındaki iki şamandıra. Tekne ikisinin arasından geçer, birini döner ve bir sonraki orsa ayağına oradan başlar.', 'Deux bouées en bas du vent arrière. Un bateau passe entre elles, contourne l’une ou l’autre, et repart de là pour le bord de près suivant.', 'Due boe in fondo al lato di poppa. Una barca passa tra le due e gira l’una o l’altra, e da lì comincia il lato di bolina successivo.', 'Duas boias no fim da popa. O barco passa entre elas e contorna qualquer uma, e começa dali a próxima perna de orça.') },
    { id: 'zone', group: 'marks', term: t('Zone', 'Зона', 'Zona', 'Zone', 'Bölge', 'Zone', 'Zona', 'Zona'), see: '/learn/rules#r18', def: t(
      'The area within three hull lengths of a mark. When the first of two overlapped boats enters it, the outside boat owes the inside one mark-room.',
      'Пространство в пределах трёх корпусов от знака. Когда первая из двух связанных лодок входит в неё, внешняя должна дать внутренней место у знака.', 'El área a menos de tres esloras de una baliza. Cuando el primero de dos barcos con compromiso entra en ella, el barco exterior debe espacio en baliza al interior.', 'Der Bereich innerhalb von drei Rumpflängen um eine Bahnmarke. Wenn das erste von zwei überlappenden Booten ihn erreicht, schuldet das äußere dem inneren Bahnmarkenraum.', 'Bir şamandıranın üç gövde boyu çevresindeki alan. Bindirmedeki iki tekneden ilki buraya girdiğinde, dıştaki tekne içtekine şamandıra alanı borçludur.', 'L’espace à moins de trois longueurs de coque d’une marque. Quand le premier de deux bateaux engagés y entre, le bateau à l’extérieur doit la place à la marque au bateau à l’intérieur.', 'L’area entro tre lunghezze di scafo da una boa. Quando la prima di due barche ingaggiate vi entra, la barca all’esterno deve dare spazio alla boa a quella all’interno.', 'A área a menos de três comprimentos de casco de uma marca. Quando o primeiro de dois barcos sobrepostos entra nela, o barco de fora deve espaço de marca ao barco de dentro.') },
    { id: 'mark-room', group: 'marks', term: t('Mark-room', 'Место у знака', 'Espacio en baliza', 'Bahnmarkenraum', 'Şamandıra alanı', 'Place à la marque', 'Spazio alla boa', 'Espaço de marca'), see: '/learn/rules#r18', def: t(
      'Room for a boat to sail to the mark and round it as she should (rule 18).',
      'Место, чтобы подойти к знаку и обогнуть его как положено (правило 18).', 'Espacio para que un barco navegue hasta la baliza y la redondee como debe (regla 18).', 'Raum für ein Boot, zur Bahnmarke zu segeln und sie so zu runden, wie sie es soll (Regel 18).', 'Bir teknenin şamandıraya yelken açması ve olması gerektiği gibi dönmesi için alan (kural 18).', 'La place pour un bateau de naviguer jusqu’à la marque et de la contourner comme il le doit (règle 18).', 'Lo spazio perché una barca navighi fino alla boa e la giri come deve (regola 18).', 'Espaço para um barco velejar até a marca e contorná-la como deve (regra 18).') },
    { id: 'wide-in', group: 'marks', term: t('Wide in, tight out', 'Широкий вход, узкий выход', 'Entrar abierto, salir ceñido', 'Weit rein, eng raus', 'Geniş gir, dar çık', 'Large en entrée, serré en sortie', 'Largo in entrata, stretto in uscita', 'Entrar aberto, sair fechado'), see: '/learn/marks#wide', def: t(
      'How to round a mark: come in a little wide so the turn is smooth and you leave the mark close, sailing away high and fast on the new leg instead of drifting off it.',
      'Как огибать знак: подходить чуть шире, чтобы поворот был плавным, а уходить вплотную к знаку, сразу высоко и быстро по новому отрезку, а не отваливая от него.', 'Cómo rodear una baliza: llegar un poco abierto para que el giro sea suave y salir pegado a ella, alto y rápido en el nuevo tramo, en lugar de alejarte de él.', 'So rundet man eine Tonne: etwas weit anfahren, damit die Drehung weich ist, und eng an ihr herauskommen, hoch und schnell auf dem neuen Schenkel, statt von ihm abzutreiben.', 'Şamandıra nasıl dönülür: dönüş yumuşak olsun diye biraz geniş gelip, şamandıranın dibinden çıkarak yeni ayakta yüksek ve hızlı seyretmek; ondan uzaklaşmamak.', 'Comment contourner une bouée : arriver un peu large pour tourner en douceur et ressortir tout près d’elle, haut et vite sur le nouveau bord, au lieu de s’en écarter.', 'Come girare una boa: arrivare un po’ larghi per una curva dolce e uscire vicinissimi alla boa, alti e veloci sul nuovo lato, invece di allontanarsene.', 'Como contornar uma boia: chegar um pouco aberto para a curva ser suave e sair colado a ela, alto e rápido na nova perna, em vez de se afastar dela.') },
    { id: 'finish-line', group: 'marks', term: t('Finish line', 'Финишная линия', 'Línea de llegada', 'Ziellinie', 'Bitiş hattı', 'Ligne d’arrivée', 'Linea d’arrivo', 'Linha de chegada'), def: t(
      'The line a boat crosses to finish, from the course side, after the last mark. Often it is the start line again, crossed the other way; some courses have a line of their own.',
      'Линия, которую лодка пересекает со стороны дистанции после последнего знака, чтобы финишировать. Часто это та же стартовая линия, пройденная в обратную сторону; на некоторых дистанциях у финиша своя линия.', 'La línea que un barco cruza desde el lado del recorrido, tras la última baliza, para terminar. A menudo es la misma línea de salida cruzada en sentido contrario; algunos recorridos tienen una propia.', 'Die Linie, die ein Boot nach der letzten Tonne von der Bahnseite her überquert, um durchs Ziel zu gehen. Oft ist es wieder die Startlinie, andersherum überquert; manche Kurse haben eine eigene.', 'Teknenin bitirmek için son şamandıradan sonra parkur tarafından geçtiği hat. Çoğu zaman ters yönde geçilen start hattının kendisidir; bazı parkurların kendi hattı vardır.', 'La ligne qu’un bateau coupe depuis le côté du parcours, après la dernière bouée, pour finir. Souvent c’est la ligne de départ, coupée dans l’autre sens ; certains parcours ont la leur.', 'La linea che una barca taglia dal lato del percorso, dopo l’ultima boa, per arrivare. Spesso è di nuovo la linea di partenza, tagliata nell’altro senso; alcuni percorsi ne hanno una propria.', 'A linha que um barco cruza, do lado do percurso, depois da última boia, para chegar. Muitas vezes é a própria linha de largada, cruzada no outro sentido; alguns percursos têm uma linha própria.') },
    { id: 'penalty', group: 'right-of-way', term: t('Penalty turn', 'Штрафной оборот', 'Giro de penalización', 'Strafkringel', 'Ceza dönüşü', 'Tour de pénalité', 'Giro di penalità', 'Giro de penalidade'), see: '/learn/rules#pen', def: t(
      'A turn through a tack and a gybe, taken as soon as possible after a foul, clear of other boats. Usually two turns for a foul between boats and one for touching a mark.',
      'Оборот через поворот оверштаг и фордевинд, который делают как можно скорее после нарушения, отойдя от других лодок. Обычно два оборота за нарушение против лодки и один за касание знака.', 'Un giro con una virada y una trasluchada, hecho lo antes posible tras una falta, separado de los otros barcos. Normalmente dos giros por una falta entre barcos y uno por tocar una baliza.', 'Eine Drehung durch eine Wende und eine Halse, so bald wie möglich nach einem Foul gefahren, klar von anderen Booten. Meist zwei Drehungen für ein Foul zwischen Booten und eine für das Berühren einer Bahnmarke.', 'Bir faulden hemen sonra, diğer teknelerden uzakta atılan bir tramola ve bir kavançadan oluşan dönüş. Tekneler arası faul için genelde iki dönüş, bir şamandıraya dokunmak için bir dönüş.', 'Un tour comprenant un virement de bord et un empannage, effectué dès que possible après une faute, à l’écart des autres bateaux. En général deux tours pour une faute entre bateaux et un pour avoir touché une marque.', 'Un giro che comprende una virata e una strambata, eseguito il prima possibile dopo un’infrazione, lontano dalle altre barche. Di solito due giri per un’infrazione tra barche e uno per aver toccato una boa.', 'Um giro com uma cambada e um jibe, feito o quanto antes depois de uma infração, longe dos outros barcos. Em geral dois giros por uma infração entre barcos e um por tocar uma marca.') },
    { id: 'umpire', group: 'right-of-way', term: t('Umpire', 'Судья на воде (ампайр)', 'Juez en el agua (umpire)', 'Umpire (Schiedsrichter auf dem Wasser)', 'Su üstü hakemi (umpire)', 'Arbitre sur l’eau (umpire)', 'Umpire (giudice in acqua)', 'Árbitro na água (umpire)'), see: '/learn/rules#pen', def: t(
      'A judge on the water who rules on a foul at once, as it happens, instead of in a protest hearing afterwards. In the game the umpire calls the fouls and gives the penalty turns.',
      'Судья на воде, который решает о нарушении сразу, по ходу гонки, а не на протестовом заседании после неё. В игре ампайр фиксирует нарушения и назначает штрафные обороты.', 'Un juez en el agua que decide sobre una infracción en el momento, en lugar de en una audiencia de protesta después. En el juego, el umpire señala las infracciones y pone los giros de penalización.', 'Ein Schiedsrichter auf dem Wasser, der über einen Regelverstoß sofort entscheidet, statt danach in einer Protestverhandlung. Im Spiel erkennt der Umpire die Verstöße und verhängt die Strafkringel.', 'Bir ihlale sonradan bir protesto duruşmasında değil, anında, suyun üstünde karar veren hakem. Oyunda ihlalleri hakem belirler ve ceza dönüşlerini verir.', 'Un arbitre sur l’eau qui tranche une faute sur-le-champ, au lieu d’une instruction de réclamation après la course. Dans le jeu, l’umpire signale les fautes et donne les tours de pénalité.', 'Un giudice in acqua che decide su un’infrazione subito, mentre accade, invece che in un’udienza di protesta dopo. Nel gioco l’umpire segnala le infrazioni e assegna i giri di penalità.', 'Um juiz na água que decide sobre uma infração na hora, em vez de numa audiência de protesto depois. No jogo, o umpire aponta as infrações e dá os giros de penalidade.') },
    { id: 'mainsail', group: 'boat', term: t('Mainsail (main)', 'Грот', 'Mayor', 'Großsegel', 'Grandi (ana yelken)', 'Grand-voile', 'Randa', 'Vela grande'), see: '/learn/trim#sheet', def: t(
      'The big sail behind the mast, along the boom. It drives the boat and also helps steer her: pulled in it turns her towards the wind, eased it lets her bear away.',
      'Большой парус за мачтой, вдоль гика. Он гонит лодку и помогает рулить: выбранный — приводит её к ветру, потравленный — даёт увалиться.', 'La vela grande detrás del mástil, a lo largo de la botavara. Impulsa el barco y además ayuda a gobernarlo: cazada lo hace orzar, suelta lo deja arribar.', 'Das große Segel hinter dem Mast, am Baum entlang. Es treibt das Boot an und hilft beim Steuern: dicht geholt luvt es an, gefiert lässt es das Boot abfallen.', 'Direğin arkasında, bom boyunca uzanan büyük yelken. Tekneyi yürütür ve dümene de yardım eder: kazanılınca tekneyi rüzgâra döndürür, laçka edilince düşmesine izin verir.', 'La grande voile derrière le mât, le long de la bôme. Elle fait avancer le bateau et aide aussi à barrer : bordée, elle le fait lofer ; choquée, elle le laisse abattre.', 'La grande vela dietro l’albero, lungo il boma. Spinge la barca e aiuta anche a governarla: cazzata la fa orzare, lascata la lascia poggiare.', 'A vela grande atrás do mastro, ao longo da retranca. Ela impulsiona o barco e também ajuda a governá-lo: caçada, faz o barco orçar; solta, deixa-o arribar.') },
    { id: 'jib', group: 'boat', term: t('Jib', 'Стаксель', 'Foque', 'Fock', 'Flok', 'Foc', 'Fiocco', 'Buja'), see: '/learn/trim#sheet', def: t(
      'The sail in front of the mast, set on the forestay. Upwind it works with the mainsail, and its telltales show the trim best.',
      'Парус перед мачтой, поставленный на штаг. На острых курсах он работает вместе с гротом, а его колдунчики лучше всего показывают настройку.', 'La vela delante del mástil, envergada en el estay. Ciñendo trabaja junto con la mayor, y sus catavientos son los que mejor muestran el trimado.', 'Das Segel vor dem Mast, am Vorstag gesetzt. Am Wind arbeitet es mit dem Großsegel zusammen, und seine Windfäden zeigen den Trimm am besten.', 'Direğin önünde, ön istralyaya basılan yelken. Orsada grandiyle birlikte çalışır ve trimi en iyi onun rüzgâr ipleri gösterir.', 'La voile devant le mât, établie sur l’étai. Au près elle travaille avec la grand-voile, et ses penons montrent le mieux le réglage.', 'La vela davanti all’albero, inferita sullo strallo. Di bolina lavora insieme alla randa, e i suoi filetti mostrano meglio la regolazione.', 'A vela à frente do mastro, envergada no estai. Na orça ela trabalha junto com a vela grande, e suas fitas de vento mostram melhor a regulagem.') },
    { id: 'boom', group: 'boat', term: t('Boom', 'Гик', 'Botavara', 'Baum', 'Bom', 'Bôme', 'Boma', 'Retranca'), see: '/learn/tack#gybe', def: t(
      'The spar along the foot of the mainsail. It swings across in a tack or a gybe, and the side it’s on tells you the tack: out to port, she is on starboard.',
      'Рангоут вдоль нижней шкаторины грота. При повороте он перекидывается на другой борт, и по нему виден галс: гик слева — лодка на правом галсе.', 'La percha a lo largo del pujamen de la mayor. Pasa al otro lado al virar o trasluchar, y el lado en que está te dice la amura: a babor, el barco va amurado a estribor.', 'Die Spiere am Unterliek des Großsegels entlang. Bei einer Wende oder Halse schwingt er hinüber, und seine Seite zeigt den Bug: steht er an Backbord, segelt das Boot auf Steuerbordbug.', 'Grandinin alt kenarı boyunca uzanan direk. Tramola ya da kavançada karşı tarafa geçer; hangi tarafta olduğu kontrayı gösterir: iskeledeyse tekne sancak kontradadır.', 'L’espar le long de la bordure de la grand-voile. Il passe de l’autre côté au virement ou à l’empannage, et son côté indique les amures : à bâbord, le bateau est tribord amures.', 'L’asta lungo la base della randa. Passa dall’altra parte in virata o in strambata, e il suo lato dice le mure: a sinistra, la barca è mure a dritta.', 'A verga ao longo da esteira da vela grande. Ela passa para o outro lado na cambada ou no jibe, e o seu lado indica a amura: a bombordo, o barco está amurado a boreste.') },
    { id: 'gennaker', group: 'boat', term: t('Gennaker (kite)', 'Генакер', 'Gennaker (kite)', 'Gennaker (Spi)', 'Gennaker (balon)', 'Gennaker (spi asymétrique)', 'Gennaker (kite)', 'Gennaker (balão assimétrico)'), see: '/learn/downwind', def: t(
      'A big, light, asymmetric sail set from the bow for sailing downwind.',
      'Большой лёгкий асимметричный парус, который ставят с носа для попутных курсов.', 'Una vela grande, ligera y asimétrica, izada desde la proa para navegar de popa.', 'Ein großes, leichtes, asymmetrisches Segel, das vom Bug aus zum Segeln vor dem Wind gesetzt wird.', 'Pruvadan açılan, rüzgâraltına yelken açmak için kullanılan büyük, hafif, asimetrik bir yelken.', 'Une grande voile légère et asymétrique, envoyée à l’avant pour naviguer au portant.', 'Una vela grande, leggera e asimmetrica, issata a prua per navigare nelle andature portanti.', 'Uma vela grande, leve e assimétrica, içada na proa para velejar em popa.') },
    { id: 'code-zero', group: 'boat', term: t('Code zero', 'Код зеро', 'Código cero', 'Code Zero', 'Code zero', 'Code zéro', 'Code zero', 'Code zero'), def: t(
      'A flat, light sail set from the bowsprit on a furler, for reaching in light air: it sails closer to the wind than the gennaker, and unrolls and furls in seconds.',
      'Плоский лёгкий парус на бушприте со скруткой — для полных курсов в слабый ветер: идёт острее генакера, а раскручивается и скручивается за секунды.', 'Una vela plana y ligera izada desde el botalón en un enrollador, para el través con poco viento: navega más cerca del viento que el gennaker y se despliega y enrolla en segundos.', 'Ein flaches, leichtes Segel am Bugspriet auf einer Rollanlage, für Raumschotskurse bei wenig Wind: es segelt höher am Wind als der Gennaker und rollt sich in Sekunden aus und ein.', 'Baş bastonundan sarma sistemle basılan düz ve hafif yelken; hafif havada apaz için: gennakerden daha dar açıyla gider, saniyeler içinde açılıp sarılır.', 'Une voile plate et légère, envoyée depuis le bout-dehors sur un enrouleur, pour le largue par petit temps : elle remonte plus près du vent que le gennaker, et se déroule et s’enroule en quelques secondes.', 'Una vela piatta e leggera issata dal bompresso su un avvolgitore, per le andature al lasco con poco vento: stringe più del gennaker e si srotola e si avvolge in pochi secondi.', 'Uma vela plana e leve, içada do gurupés num enrolador, para o través com pouco vento: veleja mais perto do vento que o gennaker e se abre e se enrola em segundos.') },
    { id: 'sheet', group: 'boat', term: t('Sheet and trim', 'Шкот и настройка', 'Escota y trimado', 'Schot und Trimm', 'İskota ve trim', 'Écoute et réglage', 'Scotta e regolazione', 'Escota e regulagem'), see: '/learn/trim', def: t(
      'The sheet is the rope that pulls a sail in or lets it out; trimming is setting it right for the wind. Too far out and the sail flaps, too far in and it stalls.',
      'Шкот — снасть, которой парус выбирают или травят; настройка — поставить парус правильно к ветру. Перетравил — парус полощет, перебрал — срывается поток.', 'La escota es el cabo que cobra una vela o la suelta; trimar es ponerla bien para el viento. Demasiado suelta y la vela aletea, demasiado cazada y se para.', 'Die Schot ist das Tau, das ein Segel dichtholt oder auffiert; Trimmen heißt, es richtig auf den Wind einzustellen. Zu weit offen, und das Segel flattert, zu weit dicht, und es strömt ab.', 'İskota, yelkeni çeken ya da bırakan halattır; trim, yelkeni rüzgâra göre ayarlamaktır. Çok bırakılırsa yelken çırpınır, çok çekilirse akım kopar.', 'L’écoute est le cordage qui borde ou choque une voile ; la régler, c’est l’ajuster au vent. Trop choquée, la voile faseye ; trop bordée, elle décroche.', 'La scotta è la cima che cazza o lasca una vela; regolarla vuol dire metterla giusta per il vento. Troppo lascata e la vela sbatte, troppo cazzata e stalla.', 'A escota é o cabo que caça ou folga uma vela; regular é ajustá-la para o vento. Folgada demais, a vela paneja; caçada demais, ela estola.') },
    { id: 'telltales', group: 'boat', term: t('Telltales', 'Колдунчики', 'Catavientos', 'Windfäden', 'Rüzgâr ipleri', 'Penons', 'Filetti', 'Fitas de vento'), see: '/learn/trim#sheet', def: t(
      'Short strips of wool or ribbon on the sails. Both streaming back, the trim is right; the inside one lifting, pull in or bear away; the outside one lifting, ease out or head up.',
      'Короткие ленточки или шерстинки на парусах. Обе тянутся назад — настройка верная; поднимается внутренняя (наветренная) — выберите шкот или увалитесь; внешняя — потравите или приведитесь.', 'Tiras cortas de lana o cinta en las velas. Si las dos van hacia atrás, el trimado es correcto; si se levanta la de dentro, caza o arriba; si se levanta la de fuera, suelta u orza.', 'Kurze Woll- oder Bandfäden an den Segeln. Wehen beide nach hinten, stimmt der Trimm; hebt sich der innere, hol dicht oder fall ab; hebt sich der äußere, fier oder luv an.', 'Yelkenlerdeki kısa yün ya da kurdele şeritler. İkisi de geriye akıyorsa trim doğrudur; içteki kalkıyorsa iskotayı kazan ya da düş; dıştaki kalkıyorsa laçka et ya da orsala.', 'De courts brins de laine ou de ruban sur les voiles. Les deux filent vers l’arrière : le réglage est bon ; celui de l’intérieur se lève : borde ou abats ; celui de l’extérieur se lève : choque ou lofe.', 'Brevi fili di lana o di nastro sulle vele. Se scorrono entrambi all’indietro la regolazione è giusta; se si alza quello interno, cazza o poggia; se si alza quello esterno, lasca od orza.', 'Fitinhas curtas de lã ou fita nas velas. As duas voando para trás, a regulagem está certa; a de dentro levantando, cace ou arribe; a de fora levantando, solte ou orce.') },
    { id: 'reef', group: 'boat', term: t('Reef', 'Риф', 'Rizo', 'Reff', 'Camadan', 'Ris', 'Terzarolo', 'Rizo'), see: '/learn/trim#blow', def: t(
      'Making the mainsail smaller in a strong wind, so the boat heels less and stays fast.',
      'Уменьшение площади грота в сильный ветер, чтобы лодка меньше кренилась и шла быстрее.', 'Reducir la mayor con viento fuerte, para que el barco escore menos y siga rápido.', 'Das Großsegel bei starkem Wind kleiner machen, damit das Boot weniger krängt und schnell bleibt.', 'Sert rüzgârda ana yelkeni küçültmek; böylece tekne daha az yatar ve hızlı kalır.', 'Réduire la grand-voile dans un vent fort, pour que le bateau gîte moins et reste rapide.', 'Ridurre la randa con vento forte, così la barca sbanda meno e resta veloce.', 'Diminuir a vela grande com vento forte, para o barco adernar menos e continuar rápido.') },
    { id: 'backing', group: 'boat', term: t('Backing the main', 'Грот на ветер (задний ход)', 'Acuartelar la mayor', 'Großsegel backhalten', 'Grandiyi kontra basmak', 'Grand-voile à contre', 'Randa a collo', 'Aquartelar a vela grande'), see: '/learn/start#hold', def: t(
      'Pushing the boom out against the wind, head to wind with the sheet right out, so the boat stops and then moves backwards: how a boat holds her spot on the line before the start.',
      'Вынести гик против ветра, стоя носом к ветру с полностью потравленным шкотом, чтобы лодка остановилась и пошла назад: так держат место на линии перед стартом.', 'Empujar la botavara contra el viento, aproados y con la escota totalmente suelta, para que el barco se pare y luego vaya hacia atrás: así se guarda el sitio en la línea antes de la salida.', 'Den Baum gegen den Wind hinausdrücken, im Wind stehend mit ganz gefierter Schot, damit das Boot stoppt und dann rückwärts fährt: so hält ein Boot vor dem Start seinen Platz an der Linie.', 'Baş rüzgâra dönükken iskota tamamen laçka, bomu rüzgâra karşı dışarı itmek; tekne durur, sonra geri gider: start öncesi hattaki yer böyle korunur.', 'Repousser la bôme contre le vent, face au vent et l’écoute toute choquée, pour que le bateau s’arrête puis recule : c’est ainsi qu’on garde sa place sur la ligne avant le départ.', 'Spingere il boma fuori contro il vento, prua al vento e con la scotta tutta lascata, perché la barca si fermi e poi vada indietro: così si tiene il posto sulla linea prima della partenza.', 'Empurrar a retranca contra o vento, aproado e com a escota toda solta, para o barco parar e depois andar para trás: é assim que se guarda o lugar na linha antes da largada.') },
  ];
  return terms;
}
